// Единое изображение-заглушка для примеров (находится в public)
// По задаче: в public/blog есть фотографии, пронумерованные 1..22 — если у статьи есть id 1..22,
// используем соответствующее изображение /blog/<id>.(png|jpg). Иначе — fallback.
const FALLBACK_IMG = "/fon.png" as const;

// backward compatibility: some posts use `img` variable — keep alias
const img = FALLBACK_IMG;

// Помощник: вернёт путь к картинке в /public/blog для id 1..22 (учитывает расширение .png или .jpg)
function imgForId(id?: number): string {
	if (!id) return FALLBACK_IMG;
	// Файлы в public/blog: 1.png..21.png и 22.jpg
	if (id >= 1 && id <= 21) return `/blog/${id}.png`;
	if (id === 22) return `/blog/22.jpg`;
	// Нестандартные размещения (uploads):
	if (id === 23) return `/uploads/blog-dishes.jpg`;
	return FALLBACK_IMG;
}

