export function getAllPosts(): ReadonlyArray<BlogPost> {
	// Публикуем статьи с id 1..23 (22 — сервировка, 23 — декоративная посуда) в порядке УБЫВАНИЯ id
	// При добавлении новых постов >23 расширить диапазон.
	return posts
		.filter(p => typeof p.id === 'number' && p.id >= 1 && p.id <= 23)
		.sort((a, b) => (b.id! - a.id!));
}

export function getPostBySlug(slug: string): BlogPost | undefined {
	return getAllPosts().find((p) => p.slug === slug);
}

export function getRelatedPosts(currentSlug: string, category: string, limit = 3): ReadonlyArray<BlogPost> {
	const published = getAllPosts();
	const sameCategory = published.filter((p) => p.slug !== currentSlug && p.category === category).slice(0, limit);
	if (sameCategory.length >= limit) return sameCategory;
	const rest = published.filter((p) => p.slug !== currentSlug && !sameCategory.includes(p)).slice(0, limit - sameCategory.length);
	return [...sameCategory, ...rest];
}

